def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    for i, op in enumerate(ops):
        tokens = op.split()
        if not tokens:
            rejected.append(i)
            continue

        verb = tokens[0]
        success = False
        record = None

        if verb == "open" and len(tokens) == 3:
            name, amount_text = tokens[1], tokens[2]
            if amount_text.isdigit() and all("0" <= c <= "9" for c in amount_text) and name not in balances:
                amount = int(amount_text)
                balances[name] = amount
                record = ("open", name)
                success = True

        elif verb == "deposit" and len(tokens) == 3:
            name, amount_text = tokens[1], tokens[2]
            if amount_text.isdigit() and all("0" <= c <= "9" for c in amount_text) and int(amount_text) > 0 and name in balances:
                amount = int(amount_text)
                balances[name] += amount
                record = ("balance", name, -amount)
                success = True

        elif verb == "withdraw" and len(tokens) == 3:
            name, amount_text = tokens[1], tokens[2]
            if amount_text.isdigit() and all("0" <= c <= "9" for c in amount_text) and int(amount_text) > 0 and name in balances:
                amount = int(amount_text)
                if name not in frozen and balances[name] >= amount:
                    balances[name] -= amount
                    record = ("balance", name, amount)
                    success = True

        elif verb == "transfer" and len(tokens) == 4:
            src, dst, amount_text = tokens[1], tokens[2], tokens[3]
            if amount_text.isdigit() and all("0" <= c <= "9" for c in amount_text) and int(amount_text) > 0 and src != dst and src in balances and dst in balances:
                amount = int(amount_text)
                if src not in frozen and balances[src] >= amount:
                    balances[src] -= amount
                    balances[dst] += amount
                    record = ("transfer", src, dst, amount)
                    success = True

        elif verb == "freeze" and len(tokens) == 2:
            name = tokens[1]
            if name in balances and name not in frozen:
                frozen.add(name)
                record = ("frozen", name, False)
                success = True

        elif verb == "unfreeze" and len(tokens) == 2:
            name = tokens[1]
            if name in balances and name in frozen:
                frozen.remove(name)
                record = ("frozen", name, True)
                success = True

        elif verb == "undo" and len(tokens) == 1:
            if history:
                record = history.pop()
                kind = record[0]
                if kind == "open":
                    name = record[1]
                    del balances[name]
                    frozen.discard(name)
                elif kind == "balance":
                    _, name, delta = record
                    balances[name] += delta
                elif kind == "transfer":
                    _, src, dst, amount = record
                    balances[src] += amount
                    balances[dst] -= amount
                elif kind == "frozen":
                    _, name, previous = record
                    if previous:
                        frozen.add(name)
                    else:
                        frozen.discard(name)
                success = True

        if success:
            if verb != "undo":
                history.append(record)
        else:
            rejected.append(i)

    return balances, rejected
